{
  "severity": "CRITICAL",
  "override_triggered": true,
  "root_cause": {
    "file": "app/services/billing.py",
    "line": 46,
    "commit": "a8f3b2c",
    "author": "dev_alex",
    "flaw_explanation": "Raw `engine.connect()` is opened without a context manager (`with`) or `db.close()`. Under high request volume, database connection handles leak until pool limit (20 handles) is reached, starving all subsequent requests."
  },
  "remediation": {
    "action": "drain_db_connections",
    "patch": "--- a/app/services/billing.py\n+++ b/app/services/billing.py\n@@ -45,6 +45,9 @@ def fetch_user_balance(user_id: str):\n-    db = engine.connect()\n-    res = db.execute('SELECT balance FROM users WHERE id = %s', (user_id,))\n-    return res.fetchone()[0]\n+    with engine.connect() as db:\n+        res = db.execute('SELECT balance FROM users WHERE id = %s', (user_id,))\n+        return res.fetchone()[0]\n"
  }
}

{
  "severity": "HIGH",
  "override_triggered": false,
  "root_cause": {
    "file": "app/routers/notify.py",
    "line": 88,
    "commit": "b91f04e",
    "author": "dev_sarah",
    "flaw_explanation": "Synchronous `requests.post()` invoked directly inside async route handler blocks the main asyncio event loop thread for up to 30 seconds per request, causing cascading HTTP 504 gateway timeouts."
  },
  "remediation": {
    "action": "restart_service",
    "patch": "--- a/app/routers/notify.py\n+++ b/app/routers/notify.py\n@@ -88,1 +88,2 @@\n-    res = requests.post('https://api.resend.com/emails', json=payload, timeout=30)\n+    async with httpx.AsyncClient() as client:\n+        res = await client.post('https://api.resend.com/emails', json=payload, timeout=30.0)\n"
  }
}

{
  "severity": "CRITICAL",
  "override_triggered": true,
  "root_cause": {
    "file": "app/services/activity_logger.py",
    "line": 34,
    "commit": "f472e11",
    "author": "dev_chris",
    "flaw_explanation": "`GLOBAL_LOG_CACHE` list grows unbounded in process memory without periodic eviction, deque maxlen constraint, or flush to disk, eventually triggering Linux OOM killer."
  },
  "remediation": {
    "action": "flush_cache",
    "patch": "--- a/app/services/activity_logger.py\n+++ b/app/services/activity_logger.py\n@@ -10,2 +10,2 @@\n-GLOBAL_LOG_CACHE = []\n+from collections import deque\n+GLOBAL_LOG_CACHE = deque(maxlen=1000)\n"
  }
}

